def _stress(block, maps):
    gain, bias = maps[np.asarray(block['lab_id'])].T
    return (block['past_stress_cmd'] * gain[:, None] + bias[:, None], block['stress_hold_cmd'] * gain + bias)

def _fit(train, x, maps, dt, time):
    from scipy.optimize import least_squares
    hist, hold = _stress(train, maps)
    cov = np.column_stack((np.ones(len(x)), x))
    eps = train['strain_curves_obs'] - train['strain_0'][:, None]
    rate = train['instant_rate_obs']
    y = np.r_[eps.ravel(), rate]
    ncurve = eps.size

    def design(taus):
        a, b = _design(taus, hist, hold, cov, dt, time)
        return np.vstack((a.reshape(-1, 7), b))

    def unpack(p):
        return np.array([p[0], p[0] + (8.0 - p[0]) * p[1]])

    def residual(p):
        return design(unpack(p)) @ p[2:] - y
    bounds = (np.r_[0.2, 1e-05, np.full(7, -np.inf)], np.r_[7.999, 1.0, np.full(7, np.inf)])
    starts = []
    for t1, t2 in ((0.27, 1.2), (0.43, 3.0), (0.65, 5.5), (1.0, 2.0), (1.3, 6.0), (2.5, 7.5)):
        A = design(np.array([t1, t2]))
        w = np.linalg.lstsq(A, y, rcond=None)[0]
        starts.append(np.r_[t1, (t2 - t1) / (8.0 - t1), w])
    prelim = [least_squares(residual, p, bounds=bounds, loss='soft_l1', f_scale=0.05, max_nfev=85) for p in starts]
    best = min(prelim, key=lambda opt: opt.cost)
    p = best.x
    for _ in range(2):
        e = residual(p)
        scale = np.r_[np.full(ncurve, 2.5 * _mad(e[:ncurve])), np.full(len(rate), 2.5 * _mad(e[ncurve:]))]
        opt = least_squares(lambda q: residual(q) / scale, p, bounds=bounds, loss='cauchy', max_nfev=100)
        p = opt.x
    return (unpack(p), p[2:])
